<section class="shophero"><h1>فروشگاه نامیرا</h1><p class="muted">تابلو، قاب، پوستر و محصولات فرهنگی</p></section><div class="layout"><form class="filters" method="get" action="/index.php"><input type="hidden" name="page" value="shop"><h3>دسته‌بندی و فیلتر</h3><label for="productq">جست‌وجو</label><input id="productq" name="q" value="<?= e($_GET['q']??'') ?>"><label for="shopcat">دسته محصول</label><input id="shopcat" name="category" value="<?= e($_GET['category']??'') ?>"><label for="max_price">حداکثر قیمت (تومان)</label><input id="max_price" name="max_price" type="number" min="0" value="<?= e($_GET['max_price']??'') ?>"><label for="sort">مرتب‌سازی</label><select name="sort" id="sort"><option value="new">جدیدترین</option><option value="price" <?= ($_GET['sort']??'')==='price'?'selected':'' ?>>ارزان‌ترین</option></select><p><button class="primary">اعمال فیلتر</button></p></form><section><?php if(!$products): ?><p class="empty">هنوز محصولی منتشر نشده است.</p><?php else: ?><div class="products"><?php foreach($products as $p): ?><article class="product"><a href="<?= e(url('product',['id'=>$p['id']])) ?>"><?php if($p['image_id']): ?><img loading="lazy" src="<?= e(url('media',['id'=>$p['image_id']])) ?>" alt="<?= e($p['title']) ?>"><?php else: ?><div class="product-placeholder">نامیرا</div><?php endif ?><h3><?= e($p['title']) ?></h3></a><p class="muted"><?= e($p['attributes']) ?></p><?php if($p['sale_price']!==null): ?><span class="strike"><?= fa(number_format((int)$p['price'])) ?></span><?php endif ?><div class="price"><?= fa(number_format((int)($p['sale_price']??$p['price']))) ?> <small>تومان</small></div><form method="post"><?= Namira\Security::field() ?><input type="hidden" name="action" value="cart"><input type="hidden" name="variant_id" value="<?= $p['variant_id'] ?>"><input type="hidden" name="quantity" value="1"><button <?= $p['stock']<1?'disabled':'' ?>><?= $p['stock']>0?'+ افزودن به سبد خرید':'ناموجود' ?></button></form></article><?php endforeach ?></div><?php endif ?></section></div>
